import Foundation
import Synchronization
import Testing
@testable import NotTennaPodCore

/// A synthetic M4A: ftyp, a large mdat of generated bytes, and moov/udta/chpl at the end or after `moovAfter` bytes
/// of mdat (followed by the rest). Built in memory; nothing to commit.
enum SparseM4A {
    static let titles = ["Opening", "Middle", "Closing"]
    static let expected: [String?] = titles
    static func atom(_ type: String, _ body: Data) -> Data {
        var data = Data()
        withUnsafeBytes(of: UInt32(8 + body.count).bigEndian) { data.append(contentsOf: $0) }
        data.append(contentsOf: Array(type.utf8)); data.append(body)
        return data
    }
    static var moov: Data {
        var chpl = Data([1, 0, 0, 0, 0])
        withUnsafeBytes(of: UInt32(titles.count).bigEndian) { chpl.append(contentsOf: $0) }
        for (index, title) in titles.enumerated() {
            withUnsafeBytes(of: (Int64(index) * 600_000 * 10_000).bigEndian) { chpl.append(contentsOf: $0) }
            chpl.append(UInt8(title.utf8.count)); chpl.append(contentsOf: Array(title.utf8))
        }
        return atom("moov", atom("udta", atom("chpl", chpl)))
    }
    static func file(mdat: Int, moovAfter: Int? = nil) -> Data {
        var data = atom("ftyp", Data("M4A ".utf8) + Data(count: 4) + Data("M4A isom".utf8))
        if let moovAfter {
            data.append(atom("mdat", Data(repeating: 0x5A, count: moovAfter)))
            data.append(moov)
            data.append(atom("mdat", Data(repeating: 0x5B, count: mdat - moovAfter)))
        } else {
            data.append(atom("mdat", Data(repeating: 0x5A, count: mdat)))
            data.append(moov)
        }
        return data
    }

    /// Serves `file` (from `body()`), honouring single Range requests and If-Range when `ranges`.
    final class Server: Sendable {
        private final class Script: Sendable {
            let file: Mutex<Data>
            let etag = Mutex<String?>("\"v1\"")
            let served = Mutex(0)
            init(_ file: Data) { self.file = Mutex(file) }
        }
        let server: LoopbackHTTPServer
        private let script: Script
        init(_ file: Data, ranges: Bool, declaresLength: Bool = true, hold: Bool = false, changeAfterFirst: Bool = false,
             pace: Int? = nil, unknownTotal: Bool = false, onClientDisconnect: (@Sendable () -> Void)? = nil) async throws {
            let script = Script(file)
            self.script = script
            server = try await LoopbackHTTPServer.start(onClientDisconnect: onClientDisconnect) { request in
                let file = script.file.withLock { $0 }, etag = script.etag.withLock { $0 }
                // The publisher replaces the file (a new ETag) once the first request is answered.
                if script.served.withLock({ $0 += 1; return $0 }) == 1, changeAfterFirst { script.etag.withLock { $0 = "\"v2\"" } }
                var headers = ["Content-Type": "audio/mp4"]
                if let etag { headers["ETag"] = etag }
                if ranges, let range = request.headers["range"], range.hasPrefix("bytes="),
                   request.headers["if-range"] == nil || request.headers["if-range"] == etag {
                    let bounds = range.dropFirst(6).split(separator: "-").compactMap { Int($0) }
                    if bounds.count == 2, bounds[0] < file.count {
                        let end = min(bounds[1], file.count - 1)
                        headers["Content-Range"] = "bytes \(bounds[0])-\(end)/\(unknownTotal ? "*" : String(file.count))"
                        return .init(status: 206, headers: headers, body: file[bounds[0]...end], pace: pace)
                    }
                }
                if hold { return .init(headers: headers, body: file.prefix(16_384), keepConnectionOpen: true, includeAutomaticContentLength: false) }
                return .init(headers: headers, body: file, includeAutomaticContentLength: declaresLength, pace: pace)
            }
        }
        var url: URL { server.url.deletingLastPathComponent().appendingPathComponent("episode.m4a") }
        var requests: [LoopbackHTTPServer.Request] { server.requests }
        func change(_ file: Data? = nil, etag: String?) {
            if let file { script.file.withLock { $0 = file } }
            script.etag.withLock { $0 = etag }
        }
        deinit { server.stop() }
    }
}

extension RemoteChapterMediaReaderTests {
    private static let mib = 1024 * 1024
    private static let block = 65_536
    private static func allowance(_ bytes: Int, restricted: Bool = true) -> AuxiliaryNetworkAdmission.Allowance {
        .init(bytes: bytes, restricted: restricted, pathLocked: false)
    }
    private static let reader = RemoteChapterMediaReader(proxy: .init())
    /// What one request may take past the bytes it asked for when the fixture writes 16 KiB at a time (the delivered
    /// chunk that crossed the count). A fixed acceptance allowance for the paced fixture, not a platform guarantee.
    private static let pace = 16_384
    private static let pacedSlack = 131_072

    /// A 40 MB mdat with moov at the end, Range supported: only the blocks the parser reads are fetched, each from its
    /// aligned offset with If-Range, at most four blocks in all.
    @Test func distantMoovRangedReadsOnlyItsBlocks() async throws {
        let server = try await SparseM4A.Server(SparseM4A.file(mdat: 40_000_000), ranges: true)
        let (chapters, consumed) = try await Self.reader.readTransfer(url: server.url, allowance: Self.allowance(5 * Self.mib))
        #expect(chapters?.map(\.title) == SparseM4A.expected)
        #expect(consumed <= 4 * Self.block, "consumed \(consumed)")
        let ranges = server.requests.map { $0.headers["range"] ?? "" }
        #expect(ranges.first == "bytes=0-65535" && ranges.count <= 4)
        for (index, request) in server.requests.enumerated() {
            let start = Int(request.headers["range"]?.dropFirst(6).prefix { $0 != "-" } ?? "") ?? -1
            #expect(start >= 0 && start % Self.block == 0)
            if index > 0 { #expect(request.headers["if-range"] == "\"v1\"") }
        }
    }

    /// Range ignored and moov 40 MB in: the read that would reach it is refused before any request, with the typed
    /// limit error (not a cancellation, not "no chapters"); only the first 64 KiB were taken (paced fixture: plus at
    /// most the fixed delivery allowance), then the connection was left, and no chunk was accepted after the stop.
    @Test(arguments: [5, 16]) func distantMoovRangeIgnoredIsRefusedBeforeRequesting(budgetMiB: Int) async throws {
        let server = try await SparseM4A.Server(SparseM4A.file(mdat: 40_000_000), ranges: false, pace: Self.pace)
        let budget = FeedTransferBudget(limit: budgetMiB * Self.mib)
        await #expect(throws: ChapterMediaBudgetExceeded(restricted: budgetMiB == 5)) {
            _ = try await Self.reader.readTransfer(url: server.url, allowance: Self.allowance(budgetMiB * Self.mib, restricted: budgetMiB == 5), budget: budget)
        }
        #expect(server.requests.count == 1)
        #expect(budget.consumed >= Self.block && budget.consumed <= Self.block + Self.pacedSlack, "consumed \(budget.consumed)")
#if DEBUG
        #expect(budget.charges.allSatisfy { !$0.afterStop }, "no chunk accepted after the read stopped")
#endif
    }

    /// The same read with the fixture writing the whole file at once: the outcome is the same, but how far the one
    /// delivered chunk runs past 64 KiB is up to the platform, so it is reported as a measurement, not asserted.
    @Test func distantMoovRangeIgnoredUnpacedOvershootIsMeasured() async throws {
        let server = try await SparseM4A.Server(SparseM4A.file(mdat: 40_000_000), ranges: false)
        let budget = FeedTransferBudget(limit: 5 * Self.mib)
        await #expect(throws: ChapterMediaBudgetExceeded(restricted: true)) {
            _ = try await Self.reader.readTransfer(url: server.url, allowance: Self.allowance(5 * Self.mib), budget: budget)
        }
        #expect(server.requests.count == 1)
#if DEBUG
        print("MEASUREMENT unpaced distant-moov first request: consumed \(budget.consumed) bytes for 65536 asked, largest chunk \(budget.charges.map(\.delivered).max() ?? 0)")
#else
        print("MEASUREMENT unpaced distant-moov first request: consumed \(budget.consumed) bytes for 65536 asked")
#endif
    }

    /// Range ignored and moov 3 MB in a file whose declared length (43 MB) is far over the 5 MiB budget: the prefix
    /// fits, so the chapters load. The requested prefixes stay within 4/3 of the 3 MB prefix plus a block of
    /// look-ahead; with the paced fixture each request takes at most the fixed delivery allowance more. Also with no
    /// declared length.
    @Test(arguments: [true, false]) func nearMoovRangeIgnoredSucceedsWithinBudget(declaresLength: Bool) async throws {
        let server = try await SparseM4A.Server(SparseM4A.file(mdat: 43_000_000, moovAfter: 3_000_000), ranges: false,
                                                declaresLength: declaresLength, pace: Self.pace)
        let budget = FeedTransferBudget(limit: 5 * Self.mib)
        let (chapters, consumed) = try await Self.reader.readTransfer(url: server.url, allowance: Self.allowance(5 * Self.mib), budget: budget)
        #expect(chapters?.map(\.title) == SparseM4A.expected)
        #expect(server.requests.count <= 3, "requests \(server.requests.count)")
        #expect(consumed <= 4_000_000 + 2 * Self.block + 3 * Self.pacedSlack, "consumed \(consumed)")
        #expect(consumed <= 5 * Self.mib)
#if DEBUG
        #expect(budget.charges.allSatisfy { !$0.afterStop }, "no chunk accepted after a completed request")
#endif
        #expect(server.requests.allSatisfy { $0.headers["accept-encoding"] == "identity" })
    }

    /// Ranged with an unknown total ("bytes a-b/*"): the last block is short, ending at the end of the file, and is
    /// accepted (its start and body length checked), so the terminal moov's chapters load.
    @Test func unknownTotalRangesAcceptTheShortTerminalBlock() async throws {
        let server = try await SparseM4A.Server(SparseM4A.file(mdat: 1_000_000), ranges: true, unknownTotal: true)
        let (chapters, _) = try await Self.reader.readTransfer(url: server.url, allowance: Self.allowance(5 * Self.mib))
        #expect(chapters?.map(\.title) == SparseM4A.expected)
        #expect(server.requests.allSatisfy { $0.headers["range"]?.hasPrefix("bytes=") == true })
    }

    /// Unknown totals with a terminal moov that spans several blocks (its header about 1 MB in, a 200,000-byte `free`
    /// inside it before udta/chpl and 100,000 bytes after): the parser probes the moov's last byte first, so the short
    /// terminal block teaches where the file ends before the udta block is read. That later "*" part is not a change;
    /// the chapters match the local file's and the known-total read's.
    @Test func unknownTotalsAfterTheLearnedEndAreNotAChange() async throws {
        var moov = SparseM4A.atom("free", Data(count: 200_000))
        moov.append(SparseM4A.atom("udta", SparseM4A.moov.dropFirst(16)))
        moov.append(SparseM4A.atom("free", Data(count: 100_000)))
        var file = SparseM4A.atom("ftyp", Data("M4A ".utf8) + Data(count: 4) + Data("M4A isom".utf8))
        file.append(SparseM4A.atom("mdat", Data(repeating: 0x5A, count: 1_000_000)))
        file.append(SparseM4A.atom("moov", moov))
        let local = FileManager.default.temporaryDirectory.appendingPathComponent("SparseMoov-\(UUID()).m4a")
        try file.write(to: local)
        defer { try? FileManager.default.removeItem(at: local) }
        let expected = try #require(try EmbeddedChapterReader.read(url: local))
        #expect(expected.map(\.title) == SparseM4A.expected)
        let unknown = try await SparseM4A.Server(file, ranges: true, unknownTotal: true)
        #expect(try await Self.reader.read(url: unknown.url, allowance: Self.allowance(5 * Self.mib)) == expected)
        #expect(unknown.requests.dropFirst().allSatisfy { $0.headers["if-range"] == "\"v1\"" })
        let known = try await SparseM4A.Server(file, ranges: true)
        #expect(try await Self.reader.read(url: known.url, allowance: Self.allowance(5 * Self.mib)) == expected)
    }

    /// A block cache of one block, reading two distant blocks in turn: each re-fetch is charged again, so the budget
    /// trips at the cumulative total, which equals the blocks the server sent.
    @Test func repeatedOverlapIsChargedCumulatively() async throws {
        let file = SparseM4A.file(mdat: 2_000_000)
        let server = try await SparseM4A.Server(file, ranges: true)
        let budget = FeedTransferBudget(limit: 6 * Self.block)
        let input = BoundedChapterByteInput(url: server.url, transport: RedirectingProxyTransport(transport: URLSessionFeedTransport()),
            credentials: nil, userAgent: "test", budget: budget, allowance: Self.allowance(6 * Self.block), cacheBytes: Self.block)
        defer { input.cancel() }
        let outcome: Result<Int, any Error> = await withCheckedContinuation { done in
            DispatchQueue.global().async {
                var reads = 0
                do {
                    for _ in 0..<10 {
                        for offset: Int64 in [700_000, 1_400_000] {
                            guard try input.read(at: offset, maximumCount: 16).count == 16 else { throw URLError(.badServerResponse) }
                            reads += 1
                        }
                    }
                    done.resume(returning: .success(reads))
                } catch { done.resume(returning: .failure(error)) }
            }
        }
        #expect(throws: ChapterMediaBudgetExceeded(restricted: true)) { _ = try outcome.get() }
        #expect(throws: ChapterMediaBudgetExceeded(restricted: true)) { try input.checkFailure() }
        // The first request plus five block fetches fit 6 blocks; the sixth fetch is refused before it is sent.
        #expect(server.requests.count == 6)
        #expect(budget.consumed == 6 * Self.block)
    }

    /// The server sends slowly and holds: the first request stops at what the budget allows while the read waits,
    /// and the read that needs more is refused with the typed error.
    @Test func blockingReadStopsAtTheBudgetWhileReceiving() async throws {
        let file = SparseM4A.file(mdat: 4_000_000, moovAfter: 3_000_000)
        let server = try await SparseM4A.Server(file, ranges: false, hold: true)
        let budget = FeedTransferBudget(limit: 32_768)
        let read = Task { try await Self.reader.readTransfer(url: server.url, allowance: Self.allowance(32_768), budget: budget) }
        let deadline = ContinuousClock.now + .seconds(5)
        while server.requests.isEmpty, ContinuousClock.now < deadline { try await Task.sleep(for: .milliseconds(2)) }
        try #require(server.requests.count == 1)
        try await server.server.appendResponseBody(file[16_384..<32_768], toLatestRequestFor: server.requests[0].path, isFinal: false)
        await #expect(throws: ChapterMediaBudgetExceeded(restricted: true)) { _ = try await read.value }
        #expect(server.requests.count == 1 && budget.consumed == 32_768)
    }

    /// A file changed between the requests of one read (the block request's If-Range no longer matches, so the server
    /// sends the whole file): `ChapterMediaChanged`, through the parser.
    @Test func validatorChangeThrowsChapterMediaChanged() async throws {
        let file = SparseM4A.file(mdat: 1_000_000)
        let server = try await SparseM4A.Server(file, ranges: true, pace: Self.pace)
        let budget = FeedTransferBudget(limit: Self.mib)
        let input = BoundedChapterByteInput(url: server.url, transport: RedirectingProxyTransport(transport: URLSessionFeedTransport()),
            credentials: nil, userAgent: "test", budget: budget, allowance: Self.allowance(Self.mib))
        defer { input.cancel() }
        let first: Result<Data, any Error> = await withCheckedContinuation { done in
            DispatchQueue.global().async { done.resume(returning: Result { try input.read(at: 0, maximumCount: 8) }) }
        }
        #expect(try first.get().count == 8)
        server.change(etag: "\"v2\"")
        let parsed: Result<[ParsedChapter]?, any Error> = await withCheckedContinuation { done in
            DispatchQueue.global().async { done.resume(returning: Result { try EmbeddedChapterReader.read(input: input) }) }
        }
        #expect(throws: ChapterMediaChanged.self) { _ = try parsed.get() }
        #expect(server.requests.count == 2 && server.requests.last?.headers["if-range"] == "\"v1\"")
    }

    /// With neither ETag nor Last-Modified no If-Range is invented; a changed total length is still a change.
    @Test func withoutAValidatorNoIfRangeIsSentAndAChangedTotalIsAChange() async throws {
        let file = SparseM4A.file(mdat: 1_000_000)
        let server = try await SparseM4A.Server(file, ranges: true)
        server.change(etag: nil)
        #expect(try await Self.reader.read(url: server.url)?.map(\.title) == SparseM4A.expected)
        #expect(server.requests.count > 1 && server.requests.allSatisfy { $0.headers["if-range"] == nil })
        let input = BoundedChapterByteInput(url: server.url, transport: RedirectingProxyTransport(transport: URLSessionFeedTransport()),
            credentials: nil, userAgent: "test", budget: FeedTransferBudget(limit: Self.mib), allowance: Self.allowance(Self.mib))
        defer { input.cancel() }
        let first: Result<Data, any Error> = await withCheckedContinuation { done in
            DispatchQueue.global().async { done.resume(returning: Result { try input.read(at: 0, maximumCount: 8) }) }
        }
        #expect(try first.get().count == 8)
        server.change(SparseM4A.file(mdat: 1_200_000), etag: nil)
        let later: Result<Data, any Error> = await withCheckedContinuation { done in
            DispatchQueue.global().async { done.resume(returning: Result { try input.read(at: 500_000, maximumCount: 8) }) }
        }
        #expect(throws: ChapterMediaChanged.self) { _ = try later.get() }
    }

    /// A redirect's cookie is kept for the chapter list's requests, as for pictures.
    @Test func redirectCookieIsKeptForTheChapterList() async throws {
        let data = try Data(contentsOf: try #require(Bundle.module.url(forResource: "nero-ordinary.m4a", withExtension: nil, subdirectory: "Fixtures/EmbeddedChapters")))
        let proxy = try await LoopbackHTTPServer.start { request in
            switch URL(string: request.path)?.path {
            case "/start.m4a": return .init(status: 302, headers: ["Location": "/gated.m4a", "Set-Cookie": "gate=open; Path=/"], body: Data())
            case "/gated.m4a":
                guard request.headers["cookie"]?.contains("gate=open") == true else { return .init(status: 403, body: Data()) }
                return .init(headers: ["Content-Type": "audio/mp4"], body: data)
            default: return .init(status: 404, body: Data())
            }
        }
        defer { proxy.stop() }
        let reader = RemoteChapterMediaReader(proxy: .init(kind: .http, host: "127.0.0.1", port: proxy.url.port!))
        #expect(try await reader.read(url: URL(string: "http://chapter-media.invalid/start.m4a")!)?.count == 3)
    }
}
